(4945813, 720045, 75532, '<td valign="top">looks like a doll!</td>', 'looks like a doll!', '2008-09-10 01:12:07.000000', NULL, 1),
(4945821, 719644, 32011, '<td valign="top">Great idea, and nice to see something other than a person pushing on a building/rock/etc.  Unfortunately, the crop doesn''t work for me... the foreground is way too distracting.</td>', 'Great idea, and nice to see something other than a person pushing on a building/rock/etc.  Unfortunately, the crop doesn''t work for me... the foreground is way too distracting.', '2008-09-10 01:12:49.000000', NULL, 1),
(4945823, 720129, 75532, '<td valign="top">compared to other pictures of people leaning on things, this one gives me the impression that the man was actually *trying* to move the object, the muscle in his legs are strained (it looks like) as far as pushin goes, this ones the best :)</td>', 'compared to other pictures of people leaning on things, this one gives me the impression that the man was actually *trying* to move the object, the muscle in his legs are strained (it looks like) as far as pushin goes, this ones the best :)', '2008-09-10 01:13:10.000000', NULL, 1),
(4945825, 719145, 84150, '<td valign="top">Good Idea!</td>', 'Good Idea!', '2008-09-10 01:13:25.000000', NULL, 1),
(4945850, 718456, 32011, '<td valign="top">Absolutely beautiful photo.  Colours are superb...unfortunately, I have to deduct a few point because I don''t see "someone trying to move an immovable object".</td>', 'Absolutely beautiful photo.  Colours are superb...unfortunately, I have to deduct a few point because I don''t see "someone trying to move an immovable object".', '2008-09-10 01:16:21.000000', NULL, 1),
(4945902, 718456, 97954, '<td valign="top">I love the sky in this, the lighting is great!  I can''t quite put my finger on it but something is unbalanced in it - maybe it is that the boat isn''t stronger than the foreground shoreline.</td>', 'I love the sky in this, the lighting is great!  I can''t quite put my finger on it but something is unbalanced in it - maybe it is that the boat isn''t stronger than the foreground shoreline.', '2008-09-10 01:23:35.000000', NULL, 1),
(4945931, 720255, 97954, '<td valign="top">I like the angle on this shot.</td>', 'I like the angle on this shot.', '2008-09-10 01:29:13.000000', NULL, 1),
(4945999, 720255, 32011, '<td valign="top">Brilliant photo... by far the best in the challenge.<br/> <br/>Composition and lighting are excellent... can''t really fault this at all</td>', 'Brilliant photo... by far the best in the challenge. Composition and lighting are excellent... can''t really fault this at all', '2008-09-10 01:43:46.000000', NULL, 1),
(4946058, 719636, 97270, '<td valign="top">I am assuming you referred to the bands "Muse" and "The Glass Ceiling". Very creative concept! The execution could have been a bit more powerful.. I was hoping that the floor would be cropped a little more to actually give an impression of a dwarfed room.</td>', 'I am assuming you referred to the bands "Muse" and "The Glass Ceiling". Very creative concept! The execution could have been a bit more powerful.. I was hoping that the floor would be cropped a little more to actually give an impression of a dwarfed room.', '2008-09-10 02:10:08.000000', NULL, 1),
(4946062, 720125, 97270, '<td valign="top">Please read the challenge specification again: "Take a photo of someone trying to move an immovable object."<br/> <br/>I fail to see who is moving the subject here.</td>', 'Please read the challenge specification again: "Take a photo of someone trying to move an immovable object." I fail to see who is moving the subject here.', '2008-09-10 02:11:43.000000', NULL, 1),
(4946070, 720161, 3569, '<td valign="top">DNMC he can roll it.</td>', 'DNMC he can roll it.', '2008-09-10 02:13:48.000000', NULL, 1),
(4946071, 717912, 97270, '<td valign="top">A smart composition. An automobile will for sure be immovable.. especially when the one pushing is in pumps. The shot is good technically..it just misses the aesthetic appeal.</td>', 'A smart composition. An automobile will for sure be immovable.. especially when the one pushing is in pumps. The shot is good technically..it just misses the aesthetic appeal.', '2008-09-10 02:14:00.000000', NULL, 1),
(4946075, 720141, 97270, '<td valign="top">Smart concept, but not well executed (technically). It lacks the technical strengths of a good photograph.</td>', 'Smart concept, but not well executed (technically). It lacks the technical strengths of a good photograph.', '2008-09-10 02:14:46.000000', NULL, 1),
(4946076, 720045, 3569, '<td valign="top">nice thought.</td>', 'nice thought.', '2008-09-10 02:14:47.000000', NULL, 1),
(4946077, 719047, 3569, '<td valign="top">to bad you cut the his feet off, would hve been so much better</td>', 'to bad you cut the his feet off, would hve been so much better', '2008-09-10 02:15:59.000000', NULL, 1),
(4946078, 719142, 97270, '<td valign="top">So what is immovable here..death grip? Makes sense. The shot is also well executed. still missing that aesthetic appeal.</td>', 'So what is immovable here..death grip? Makes sense. The shot is also well executed. still missing that aesthetic appeal.', '2008-09-10 02:16:10.000000', NULL, 1),
(4946080, 718556, 3569, '<td valign="top">x-lax would have been better.</td>', 'x-lax would have been better.', '2008-09-10 02:16:43.000000', NULL, 1),
(4946082, 720255, 3569, '<td valign="top">cleaver</td>', 'cleaver', '2008-09-10 02:16:51.000000', NULL, 1),
(4946087, 718882, 3569, '<td valign="top">a bit of a shoehorn, but nice b&amp;w though</td>', 'a bit of a shoehorn, but nice b&w though', '2008-09-10 02:19:19.000000', NULL, 1),
(4946090, 719954, 3569, '<td valign="top">funny, a spent cicada skin shed moving anything.  Cleaver.  :)</td>', 'funny, a spent cicada skin shed moving anything.  Cleaver.  :)', '2008-09-10 02:20:52.000000', NULL, 1),
(4946092, 719650, 3569, '<td valign="top">well over my head????</td>', 'well over my head????', '2008-09-10 02:22:01.000000', NULL, 1),
(4946099, 718730, 97270, '<td valign="top">Interesting composition. The image is a bit noisy, esp. on the hand.. owing to the ISO settings I guess. Not the best shot technically for me.</td>', 'Interesting composition. The image is a bit noisy, esp. on the hand.. owing to the ISO settings I guess. Not the best shot technically for me.', '2008-09-10 02:24:59.000000', NULL, 1),
(4946110, 720188, 97270, '<td valign="top">It is a good composition... it just might fade away in the presence of many similar shots. Good technically, lacks originality and the ''essence'' that appeals.</td>', 'It is a good composition... it just might fade away in the presence of many similar shots. Good technically, lacks originality and the ''essence'' that appeals.', '2008-09-10 02:28:16.000000', NULL, 1),
(4946115, 720260, 97270, '<td valign="top">I really do not get the essence of this image... neither is it great technically.</td>', 'I really do not get the essence of this image... neither is it great technically.', '2008-09-10 02:30:50.000000', NULL, 1),
(4946118, 719139, 97270, '<td valign="top">Not the woody again:-) Good shot, the composition not that interesting in terms of using the space and angles.</td>', 'Not the woody again:-) Good shot, the composition not that interesting in terms of using the space and angles.', '2008-09-10 02:31:46.000000', NULL, 1),
(4946128, 719644, 97270, '<td valign="top">Decent shot, faithful colors. Somehow the shot is missing an aesthetic appeal.</td>', 'Decent shot, faithful colors. Somehow the shot is missing an aesthetic appeal.', '2008-09-10 02:34:09.000000', NULL, 1),
(4946129, 718491, 97270, '<td valign="top">Great concept, but the challenge said: "someone trying to move the immovable" (please read the challenge requirements). May be I somehow dont see that being portayed.</td>', 'Great concept, but the challenge said: "someone trying to move the immovable" (please read the challenge requirements). May be I somehow dont see that being portayed.', '2008-09-10 02:34:53.000000', NULL, 1),
(4946152, 718927, 97270, '<td valign="top">I assume this image is noisy on purpose. I would be interested in finding out the camera used if it isnt. The last of the hot dogs are immovable? Kind of a weak message.</td>', 'I assume this image is noisy on purpose. I would be interested in finding out the camera used if it isnt. The last of the hot dogs are immovable? Kind of a weak message.', '2008-09-10 02:41:07.000000', NULL, 1),
(4946176, 719544, 78303, '<td valign="top">Highlights are too blownout for my tastes</td>', 'Highlights are too blownout for my tastes', '2008-09-10 02:47:44.000000', NULL, 1),
(4946177, 719139, 78303, '<td valign="top">OOF</td>', 'OOF', '2008-09-10 02:47:56.000000', NULL, 1),
(4946180, 718890, 97270, '<td valign="top">Good composition.. but lacks originality.</td>', 'Good composition.. but lacks originality.', '2008-09-10 02:48:12.000000', NULL, 1),
(4946193, 720129, 97270, '<td valign="top">Great shot, but the subject lacks originality.</td>', 'Great shot, but the subject lacks originality.', '2008-09-10 02:50:27.000000', NULL, 1),
(4946194, 719047, 97270, '<td valign="top">Great shot, lacks originality.</td>', 'Great shot, lacks originality.', '2008-09-10 02:50:39.000000', NULL, 1),
(4946196, 719842, 97270, '<td valign="top">Good shot, but the subject isnt original as you would see post voting.</td>', 'Good shot, but the subject isnt original as you would see post voting.', '2008-09-10 02:51:06.000000', NULL, 1),
(4946198, 720189, 97270, '<td valign="top">Good subject, but not as nicely executed.</td>', 'Good subject, but not as nicely executed.', '2008-09-10 02:51:24.000000', NULL, 1),
(4946200, 718291, 25355, '<td valign="top">It''s worthwhile reading the Challenge description once in a while. ;-)</td>', 'It''s worthwhile reading the Challenge description once in a while. ;-)', '2008-09-10 02:51:42.000000', NULL, 1),
(4946201, 719366, 97270, '<td valign="top">This is a good composition, could have been better with the contrast and the camera angle etc.</td>', 'This is a good composition, could have been better with the contrast and the camera angle etc.', '2008-09-10 02:51:51.000000', NULL, 1),
(4946204, 719948, 97270, '<td valign="top">Good idea, but unfortunately not original as you will see after the voting is over.</td>', 'Good idea, but unfortunately not original as you will see after the voting is over.', '2008-09-10 02:52:30.000000', NULL, 1),
(4946208, 720208, 97270, '<td valign="top">Aha! Great idea! Sharp focus. The scene could have been composed a bit more interestingly with the camera angle etc.</td>', 'Aha! Great idea! Sharp focus. The scene could have been composed a bit more interestingly with the camera angle etc.', '2008-09-10 02:53:16.000000', NULL, 1),
(4946210, 719650, 97270, '<td valign="top">What is immovable here? The expressions on the girls face are great. Nice composition, but could be better with a better camera angle... perhaps from the perspective of one of the two actors.</td>', 'What is immovable here? The expressions on the girls face are great. Nice composition, but could be better with a better camera angle... perhaps from the perspective of one of the two actors.', '2008-09-10 02:55:08.000000', NULL, 1),
(4946214, 718456, 97270, '<td valign="top">This is such a great image! The only reason I am deducting marks here are because of the challenge requirements: <br/> <br/>"Take a photo of someone trying to move an immovable object." <br/> <br/>I fail to see who is trying to move what in this scene. I assume it would the the waters trying to move the boat... but that isnt apparent here. The water is so calm.</td>', 'This is such a great image! The only reason I am deducting marks here are because of the challenge requirements:  "Take a photo of someone trying to move an immovable object."  I fail to see who is trying to move what in this scene. I assume it would the the waters trying to move the boat... but that isnt apparent here. The water is so calm.', '2008-09-10 02:57:20.000000', NULL, 1),
(4946221, 719828, 97270, '<td valign="top">This is a great shot... free from clutter.. focussing on the main subject... bright colors, sharp.</td>', 'This is a great shot... free from clutter.. focussing on the main subject... bright colors, sharp.', '2008-09-10 02:58:43.000000', NULL, 1),
(4946222, 719952, 97270, '<td valign="top">Good concept, but lacks technical depth.</td>', 'Good concept, but lacks technical depth.', '2008-09-10 02:59:10.000000', NULL, 1),
(4946227, 720148, 97270, '<td valign="top">Good composition. Misses the ''kick'' that would guarantee a ribbon, but still deserves a good score.</td>', 'Good composition. Misses the ''kick'' that would guarantee a ribbon, but still deserves a good score.', '2008-09-10 03:01:00.000000', NULL, 1),
(4946230, 719998, 97614, '<td valign="top">Garnesha festival! ;)</td>', 'Garnesha festival! ;)', '2008-09-10 03:02:24.000000', NULL, 1),
(4946232, 720029, 97270, '<td valign="top">Good shot, the composition could have been better. There are severe blocky artifacts around the silhouettes of the actors, possibly suggesting a bad compression (during JPEG conversion). Lacks technical depth.</td>', 'Good shot, the composition could have been better. There are severe blocky artifacts around the silhouettes of the actors, possibly suggesting a bad compression (during JPEG conversion). Lacks technical depth.', '2008-09-10 03:02:41.000000', NULL, 1),
(4946234, 719062, 97270, '<td valign="top">Good concept, not so good execution. The image looks faded and has chromatic aberrations.</td>', 'Good concept, not so good execution. The image looks faded and has chromatic aberrations.', '2008-09-10 03:03:28.000000', NULL, 1),
(4946239, 719434, 97270, '<td valign="top">Cute. Great technical shot. Nice angle.. good contrast. Just lacks the effort one would show when moving the immovable:-)</td>', 'Cute. Great technical shot. Nice angle.. good contrast. Just lacks the effort one would show when moving the immovable:-)', '2008-09-10 03:04:24.000000', NULL, 1),
(4946244, 719922, 97270, '<td valign="top">Now this is a great way of portraying a common subject. It shows efort, strength, the struggle, along with the technical aspects that make it a great image.</td>', 'Now this is a great way of portraying a common subject. It shows efort, strength, the struggle, along with the technical aspects that make it a great image.', '2008-09-10 03:05:41.000000', NULL, 1),
(4946247, 720053, 97270, '<td valign="top">Wow! How did you think of that? Powerful depiction of the topic. The grains add to the strength of the image.</td>', 'Wow! How did you think of that? Powerful depiction of the topic. The grains add to the strength of the image.', '2008-09-10 03:06:22.000000', NULL, 1),
(4946251, 719544, 97270, '<td valign="top">Great composition... although it certainly doesnt look like the model is trying to move the steel..</td>', 'Great composition... although it certainly doesnt look like the model is trying to move the steel..', '2008-09-10 03:07:04.000000', NULL, 1),
(4946259, 718436, 97270, '<td valign="top">Strong depiction of the subject... expresisons are great. Could have been a better composition of the scene with a more dramatic camera angle may be? Contrast not that great... faded colors are ok I think considering the topic.</td>', 'Strong depiction of the subject... expresisons are great. Could have been a better composition of the scene with a more dramatic camera angle may be? Contrast not that great... faded colors are ok I think considering the topic.', '2008-09-10 03:09:45.000000', NULL, 1),
(4946263, 720069, 97270, '<td valign="top">Deserves a high score. The scene could have been composed a bit more dramatically... and a close up might have been stronger.</td>', 'Deserves a high score. The scene could have been composed a bit more dramatically... and a close up might have been stronger.', '2008-09-10 03:10:33.000000', NULL, 1),
(4946265, 720120, 97270, '<td valign="top">What nice camera angle!! Although it doesnt depict all the effort one expects from one trying to move the immovable. Sharp, with good contrast.</td>', 'What nice camera angle!! Although it doesnt depict all the effort one expects from one trying to move the immovable. Sharp, with good contrast.', '2008-09-10 03:11:31.000000', NULL, 1),
(4946266, 719799, 97270, '<td valign="top">What nice composition! The camera angle, had it been a bit more oblique (towards the lady), would have helped more I think. Great texture on the car. Another angle would have been one that shows the actor''s expressions.</td>', 'What nice composition! The camera angle, had it been a bit more oblique (towards the lady), would have helped more I think. Great texture on the car. Another angle would have been one that shows the actor''s expressions.', '2008-09-10 03:11:35.000000', NULL, 1),
(4946268, 720255, 97270, '<td valign="top">Great shot! The B/W adds to the strength. Kudos for the idea. I would like to know where you found that clock:-)</td>', 'Great shot! The B/W adds to the strength. Kudos for the idea. I would like to know where you found that clock:-)', '2008-09-10 03:12:37.000000', NULL, 1),
(4946270, 720045, 97270, '<td valign="top">That is such an original idea. You make up with the originality what you lack in technical strength.</td>', 'That is such an original idea. You make up with the originality what you lack in technical strength.', '2008-09-10 03:13:10.000000', NULL, 1),
(4946273, 719998, 97270, '<td valign="top">Great idea. The shot itself could have been a tad more dramatic in composition. Deserves a decent high score.</td>', 'Great idea. The shot itself could have been a tad more dramatic in composition. Deserves a decent high score.', '2008-09-10 03:13:55.000000', NULL, 1),
(4946274, 720293, 97270, '<td valign="top">Trying to revive a dead fly, is that what you wanted to convey? If yes, this is a brilliant shot... with innocence.. and true to life colors.</td>', 'Trying to revive a dead fly, is that what you wanted to convey? If yes, this is a brilliant shot... with innocence.. and true to life colors.', '2008-09-10 03:14:01.000000', NULL, 1),
(4946275, 718556, 97270, '<td valign="top">Wow! I almost entered this challenge with this idea, but chose the other challenge instead. I think this is a great shot. Great composition too. Could have had a little more interesting setup, but deserves a decently high score for originality:-)</td>', 'Wow! I almost entered this challenge with this idea, but chose the other challenge instead. I think this is a great shot. Great composition too. Could have had a little more interesting setup, but deserves a decently high score for originality:-)', '2008-09-10 03:14:04.000000', NULL, 1),
(4946277, 719845, 97270, '<td valign="top">What nice composition! The execution is superb. The camera angle could have been a bit more interesting, but nevertheless, a great shot.</td>', 'What nice composition! The execution is superb. The camera angle could have been a bit more interesting, but nevertheless, a great shot.', '2008-09-10 03:14:50.000000', NULL, 1),
(4946279, 719799, 94265, '<td valign="top">I love the old car, the colour is great. The model looks a wee bit bored or something though, the inclination of her face suggests to me she''s not paying much attention to the task at hand.</td>', 'I love the old car, the colour is great. The model looks a wee bit bored or something though, the inclination of her face suggests to me she''s not paying much attention to the task at hand.', '2008-09-10 03:15:35.000000', NULL, 1),
(4946282, 720123, 97270, '<td valign="top">Intense portrayal of the topic. The scene could have been a bit more powerfully composed (perhaps with the camera close to the object looking above to the actress), but not bad. High score for originality!</td>', 'Intense portrayal of the topic. The scene could have been a bit more powerfully composed (perhaps with the camera close to the object looking above to the actress), but not bad. High score for originality!', '2008-09-10 03:16:31.000000', NULL, 1),
(4946286, 718882, 97270, '<td valign="top">Exquisite! Great composition.. the B/W adds to the beauty.</td>', 'Exquisite! Great composition.. the B/W adds to the beauty.', '2008-09-10 03:18:01.000000', NULL, 1),
(4946290, 720145, 97270, '<td valign="top">I am contemplating whether this image would have scored as high if this actress was not there. Nevertheless, decent shot. Sharp, in focus, depicts the effort one would make to move the immovable (expressins could have been better). The scene however could have been more powerful if the actress would fit in the context.</td>', 'I am contemplating whether this image would have scored as high if this actress was not there. Nevertheless, decent shot. Sharp, in focus, depicts the effort one would make to move the immovable (expressins could have been better). The scene however could have been more powerful if the actress would fit in the context.', '2008-09-10 03:20:14.000000', NULL, 1),
(4946296, 719954, 97270, '<td valign="top">Great idea, but lacks technical strength. Contrast could be improved. Camera angle could have been more dramatic. I would be interested in knowing if teh bug was alive at the time of the shoot:-) (kidding)</td>', 'Great idea, but lacks technical strength. Contrast could be improved. Camera angle could have been more dramatic. I would be interested in knowing if teh bug was alive at the time of the shoot:-) (kidding)', '2008-09-10 03:24:31.000000', NULL, 1),
(4946297, 720064, 97270, '<td valign="top">What a smashing composition! The silhouettes are powerful. The title didnt rhyme for me though.</td>', 'What a smashing composition! The silhouettes are powerful. The title didnt rhyme for me though.', '2008-09-10 03:24:39.000000', NULL, 1),
(4946298, 720089, 97270, '<td valign="top">Hah! Interesting concept. Decent execution... could have been better. The expressions do justice with the situation.</td>', 'Hah! Interesting concept. Decent execution... could have been better. The expressions do justice with the situation.', '2008-09-10 03:24:44.000000', NULL, 1),
(4946299, 719488, 97270, '<td valign="top">What great composition! Bright flowing colors... great contrast and reflection.. beautiful grey skies..</td>', 'What great composition! Bright flowing colors... great contrast and reflection.. beautiful grey skies..', '2008-09-10 03:25:05.000000', NULL, 1),
(4946300, 718700, 97270, '<td valign="top">This is in top 3 if you ask me. A great composition. I would like to know where it was shot though... the clouds towards the bottom of the image are powerful subjects in the background.</td>', 'This is in top 3 if you ask me. A great composition. I would like to know where it was shot though... the clouds towards the bottom of the image are powerful subjects in the background.', '2008-09-10 03:26:16.000000', NULL, 1),
(4946301, 720263, 97270, '<td valign="top">High score for originality. High score for technical strength. High score for a powerful topic.</td>', 'High score for originality. High score for technical strength. High score for a powerful topic.', '2008-09-10 03:26:20.000000', NULL, 1),
(4946306, 719145, 97270, '<td valign="top">This is in top 3 for me. Great angle, great depiction, great composition, great color fidelity. Nothing to complain about here. I give it a 10.</td>', 'This is in top 3 for me. Great angle, great depiction, great composition, great color fidelity. Nothing to complain about here. I give it a 10.', '2008-09-10 03:27:15.000000', NULL, 1),
(4946307, 720161, 97270, '<td valign="top">Great image. The boy has such convincing expressions. The overexposed background highlights the sbjects.</td>', 'Great image. The boy has such convincing expressions. The overexposed background highlights the sbjects.', '2008-09-10 03:27:20.000000', NULL, 1),
(4946309, 718291, 97270, '<td valign="top">Please re-read the challenge details: "Take a photo of someone trying to move an immovable object."<br/> <br/>I do not see a subject trying to move the mountains here.</td>', 'Please re-read the challenge details: "Take a photo of someone trying to move an immovable object." I do not see a subject trying to move the mountains here.', '2008-09-10 03:28:21.000000', NULL, 1),
(4946319, 719145, 67237, '<td valign="top">bright idea!! love it...8</td>', 'bright idea!! love it...8', '2008-09-10 03:33:43.000000', NULL, 1),
(4946323, 720161, 67237, '<td valign="top">love that expresion!!</td>', 'love that expresion!!', '2008-09-10 03:35:51.000000', NULL, 1),
(4946361, 720260, 37252, '<td valign="top">I am having a hard time seeing this as immovable. The image itself lacks sharp detail - almost to the point of having motion blur which in itself makes this not immovable. Giving this  5 for effort.</td>', 'I am having a hard time seeing this as immovable. The image itself lacks sharp detail - almost to the point of having motion blur which in itself makes this not immovable. Giving this  5 for effort.', '2008-09-10 03:56:50.000000', NULL, 1),
(4946364, 720189, 37252, '<td valign="top">Cute idea. I can remember as a child having being the kid trying to move and immovable adult. I would have liked to see better technicals here however, such as sharp focus, and more vibrant colors. 5</td>', 'Cute idea. I can remember as a child having being the kid trying to move and immovable adult. I would have liked to see better technicals here however, such as sharp focus, and more vibrant colors. 5', '2008-09-10 03:58:59.000000', NULL, 1),
