INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4947546, 720069, 9073, '<td valign="top">I think that a different camera angle and composition would help to bring out the emotive value here. I''d move in a bit, compose so that the foreground cross and the human with his cross were the only things in shot. Then the agony and desperation on the face may be seen more.</td>', 'I think that a different camera angle and composition would help to bring out the emotive value here. I''d move in a bit, compose so that the foreground cross and the human with his cross were the only things in shot. Then the agony and desperation on the face may be seen more.', '2008-09-10 13:32:42.000000', NULL, 1),
(4947548, 719842, 9073, '<td valign="top">I like the colours but the brightness on the nether regions draws the eyes a bit</td>', 'I like the colours but the brightness on the nether regions draws the eyes a bit', '2008-09-10 13:33:05.000000', NULL, 1),
