(4947568, 720089, 9073, '<td valign="top">Interesting idea and facial expression</td>', 'Interesting idea and facial expression', '2008-09-10 13:37:12.000000', NULL, 1),
(4947569, 718927, 95884, '<td valign="top">Some sharper post processing might eliminate some of the High-ISO noise.  And I am little bit confused as to how this meets the challenge req''s.</td>', 'Some sharper post processing might eliminate some of the High-ISO noise.  And I am little bit confused as to how this meets the challenge req''s.', '2008-09-10 13:37:26.000000', NULL, 1),
