(4949677, 719488, 46314, '<td valign="top">Could''ve cropped it a bit tighter to put more emphasis on the guy and the reflection. But I like the lighting and the idea.</td>', 'Could''ve cropped it a bit tighter to put more emphasis on the guy and the reflection. But I like the lighting and the idea.', '2008-09-11 06:22:35.000000', NULL, 1),
(4949678, 719948, 46314, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2008-09-11 06:22:45.000000', NULL, 1),
(4949679, 719366, 46314, '<td valign="top">Yeah, he''s not gonna move that...</td>', 'Yeah, he''s not gonna move that...', '2008-09-11 06:23:04.000000', NULL, 1),
(4949680, 719845, 46314, '<td valign="top">Clever idea. Nicely taken.</td>', 'Clever idea. Nicely taken.', '2008-09-11 06:23:19.000000', NULL, 1),
(4949681, 720120, 46314, '<td valign="top">Funny - I like the angle you chose.</td>', 'Funny - I like the angle you chose.', '2008-09-11 06:23:39.000000', NULL, 1),
