(4949797, 718730, 94265, '<td valign="top">Picture of the moon printed out next to your hand....? Cool idea.</td>', 'Picture of the moon printed out next to your hand....? Cool idea.', '2008-09-11 07:50:37.000000', NULL, 1),
(4949798, 719062, 94265, '<td valign="top">Bit overexposed and a wee bit too much foreground maybe; nice soft focus though, the green in the background is good.</td>', 'Bit overexposed and a wee bit too much foreground maybe; nice soft focus though, the green in the background is good.', '2008-09-11 07:51:02.000000', NULL, 1),
(4949799, 720148, 94265, '<td valign="top">Hand up in front of the scenery, or against a printed photo of scenery? Nice idea, light on the fingertips is a wee tad harsh.</td>', 'Hand up in front of the scenery, or against a printed photo of scenery? Nice idea, light on the fingertips is a wee tad harsh.', '2008-09-11 07:51:22.000000', NULL, 1),
(4949800, 718927, 94265, '<td valign="top">Too grainy/overexposed, the idea is pretty amusing though; no-one ever wants the very last dogs from the dish!</td>', 'Too grainy/overexposed, the idea is pretty amusing though; no-one ever wants the very last dogs from the dish!', '2008-09-11 07:51:48.000000', NULL, 1),
(4949802, 718291, 94265, '<td valign="top">Beautiful landscape shot but doesn''t really meet the challenge.</td>', 'Beautiful landscape shot but doesn''t really meet the challenge.', '2008-09-11 07:52:10.000000', NULL, 1),
