INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4951004, 718927, 43191, '<td valign="top">I like this. The processing is interesting and the shot tells a story. It looks like a kids sporting fundraiser or something. I can hear them saying things like "come on, you can have it for half price!" or "somebody needs to buy these ,''cause we can''t take them home".<br/>Anyway, that''s the story I see, I wonder what others see?<br/>Bumping to a 9</td>', 'I like this. The processing is interesting and the shot tells a story. It looks like a kids sporting fundraiser or something. I can hear them saying things like "come on, you can have it for half price!" or "somebody needs to buy these ,''cause we can''t take them home".Anyway, that''s the story I see, I wonder what others see?Bumping to a 9', '2008-09-11 20:40:38.000000', NULL, 1),
(4951040, 720293, 73564, '<td valign="top">Very nice image, I like the colors and the depth, I really don''t get the immoveable thing, but this is one of the stronger images in this challenge, came back to view again, I really like how tack sharp the butterfly is compared to the rest, such fine tiny detail, and how it has green here and there like older movies, not sure if it was intentional or not, but a great image, so far my only 10.</td>', 'Very nice image, I like the colors and the depth, I really don''t get the immoveable thing, but this is one of the stronger images in this challenge, came back to view again, I really like how tack sharp the butterfly is compared to the rest, such fine tiny detail, and how it has green here and there like older movies, not sure if it was intentional or not, but a great image, so far my only 10.', '2008-09-11 21:08:44.000000', NULL, 1),
