(4953953, 719145, 92473, '<td valign="top">another one that displays great thought.well done.</td>', 'another one that displays great thought.well done.', '2008-09-13 20:19:09.000000', NULL, 1),
(4953956, 720123, 92473, '<td valign="top">the ball or whatever, looks like an orange , but it displays all the mystic. I hope you got it to move.good thinking.</td>', 'the ball or whatever, looks like an orange , but it displays all the mystic. I hope you got it to move.good thinking.', '2008-09-13 20:21:31.000000', NULL, 1),
(4953957, 719954, 92473, '<td valign="top">i thought that this was the best thing in this challenge</td>', 'i thought that this was the best thing in this challenge', '2008-09-13 20:22:40.000000', NULL, 1),
(4953966, 720263, 3936, '<td valign="top">Either you have a lot of friends to help you stage a photo, or you are braver than me.  Those officers look deadly serious.</td>', 'Either you have a lot of friends to help you stage a photo, or you are braver than me.  Those officers look deadly serious.', '2008-09-13 20:29:49.000000', NULL, 1),
(4953967, 719366, 3936, '<td valign="top">The red appears a little over saturated, and the light pole distracts a bit.  Otherwise nice pic.</td>', 'The red appears a little over saturated, and the light pole distracts a bit.  Otherwise nice pic.', '2008-09-13 20:30:43.000000', NULL, 1),
(4953968, 719434, 3936, '<td valign="top">Cute!  B&amp;W is a nice touch here.  Like the texture of the tree.</td>', 'Cute!  B&W is a nice touch here.  Like the texture of the tree.', '2008-09-13 20:31:31.000000', NULL, 1),
(4953970, 720125, 3936, '<td valign="top">Lighting is a little flat.  Would like the bus brighter.  But sure does look immovable.</td>', 'Lighting is a little flat.  Would like the bus brighter.  But sure does look immovable.', '2008-09-13 20:32:25.000000', NULL, 1),
(4953999, 719650, 3936, '<td valign="top">Not sure how this relates to immovable.  I like the lighting.</td>', 'Not sure how this relates to immovable.  I like the lighting.', '2008-09-13 21:13:14.000000', NULL, 1),
(4954000, 720089, 3936, '<td valign="top">I''m not seeng the immovable here.  Greenish cast is an interesting idea.  I like the light or reflector in the subjects hand.</td>', 'I''m not seeng the immovable here.  Greenish cast is an interesting idea.  I like the light or reflector in the subjects hand.', '2008-09-13 21:15:08.000000', NULL, 1),
(4954002, 720141, 3936, '<td valign="top">Lighting is a little flat, and contrast seems a little low.</td>', 'Lighting is a little flat, and contrast seems a little low.', '2008-09-13 21:15:57.000000', NULL, 1),
(4954004, 720123, 3936, '<td valign="top">Nice lighting, and saturation.  A compostion is a little too centered for me.  Otherwise nice work.</td>', 'Nice lighting, and saturation.  A compostion is a little too centered for me.  Otherwise nice work.', '2008-09-13 21:17:16.000000', NULL, 1),
(4954005, 720189, 3936, '<td valign="top">Oh the bane of kids the world over.  Bigger kids.  (Or maybe Dad who just won''t share.)  Nice humerous take on the challenge.</td>', 'Oh the bane of kids the world over.  Bigger kids.  (Or maybe Dad who just won''t share.)  Nice humerous take on the challenge.', '2008-09-13 21:18:14.000000', NULL, 1),
(4954007, 719047, 3936, '<td valign="top">Dang!  He bent the tree!  I like the texture.</td>', 'Dang!  He bent the tree!  I like the texture.', '2008-09-13 21:18:47.000000', NULL, 1),
(4954011, 718436, 3936, '<td valign="top">Good one.  Looks like he tore the statue in two.</td>', 'Good one.  Looks like he tore the statue in two.', '2008-09-13 21:20:56.000000', NULL, 1),
(4954013, 719828, 3936, '<td valign="top">Nice color and saturation.  Are the other kids really that much bigger?</td>', 'Nice color and saturation.  Are the other kids really that much bigger?', '2008-09-13 21:21:41.000000', NULL, 1),
(4954016, 720188, 3936, '<td valign="top">Looks like your subject is really trying.  Perhaps a closer view, with a shot of the facial expression would help here.</td>', 'Looks like your subject is really trying.  Perhaps a closer view, with a shot of the facial expression would help here.', '2008-09-13 21:23:08.000000', NULL, 1),
(4954019, 718730, 3936, '<td valign="top">Neat idea here.  But the hand doesn''t really look like it is trying to move the moon.  Contact with the moon and a different angle on the hand could help here.</td>', 'Neat idea here.  But the hand doesn''t really look like it is trying to move the moon.  Contact with the moon and a different angle on the hand could help here.', '2008-09-13 21:24:41.000000', NULL, 1),
(4954022, 720148, 3936, '<td valign="top">I like the lighting, the lighting on the hand pretty well matches the lighting on the rocks.  But the angle appears wrong, and there doesn''t appear to be any strain in the hand.  Looks more like it is resting.</td>', 'I like the lighting, the lighting on the hand pretty well matches the lighting on the rocks.  But the angle appears wrong, and there doesn''t appear to be any strain in the hand.  Looks more like it is resting.', '2008-09-13 21:26:31.000000', NULL, 1),
(4954030, 720120, 3936, '<td valign="top">I like the black and white.  Color would not have worked as well.  A little more strain, and a little less smile, would make it a bit more realisitic.  As is, nice entry.</td>', 'I like the black and white.  Color would not have worked as well.  A little more strain, and a little less smile, would make it a bit more realisitic.  As is, nice entry.', '2008-09-13 21:29:25.000000', NULL, 1),
(4954033, 719842, 3936, '<td valign="top">A bit bright, the highlights are washed out.  The focus appears a little soft also.</td>', 'A bit bright, the highlights are washed out.  The focus appears a little soft also.', '2008-09-13 21:30:20.000000', NULL, 1),
(4954036, 718291, 3936, '<td valign="top">Nope, I don''t think we can move those.  The horizon looks a little off level, but it could be an illusion, if the land is really sloping left to right.</td>', 'Nope, I don''t think we can move those.  The horizon looks a little off level, but it could be an illusion, if the land is really sloping left to right.', '2008-09-13 21:31:34.000000', NULL, 1),
(4954038, 719952, 3936, '<td valign="top">Interesting take, and a nice change from all the people leaning on rocks.  Lighting is a little flat, and focus seems a little soft.</td>', 'Interesting take, and a nice change from all the people leaning on rocks.  Lighting is a little flat, and focus seems a little soft.', '2008-09-13 21:32:41.000000', NULL, 1),
(4954040, 719948, 3936, '<td valign="top">Focus seems a little off.  By the time the eye gets to your subject, he looks a little soft.  The closer rocks are sharper.</td>', 'Focus seems a little off.  By the time the eye gets to your subject, he looks a little soft.  The closer rocks are sharper.', '2008-09-13 21:33:39.000000', NULL, 1),
(4954044, 719644, 3936, '<td valign="top">I''m not seeing immovable here.  Looks like everyone is in motion.  The white shirted person on the left, is very distracting.</td>', 'I''m not seeing immovable here.  Looks like everyone is in motion.  The white shirted person on the left, is very distracting.', '2008-09-13 21:34:56.000000', NULL, 1),
(4954047, 720260, 3936, '<td valign="top">Ineresting image.  A little bright as the white areas have lost detail and the sprout is getting close to featureless in the light center. I would suggest either more depth of field to make the hand sharp, or crop the hand out entirely.  At the same time, this still doesn''t look immovalbe.  I eat them on a regular basis and they move just fine. ;-)</td>', 'Ineresting image.  A little bright as the white areas have lost detail and the sprout is getting close to featureless in the light center. I would suggest either more depth of field to make the hand sharp, or crop the hand out entirely.  At the same time, this still doesn''t look immovalbe.  I eat them on a regular basis and they move just fine. ;-)', '2008-09-13 21:37:27.000000', NULL, 1),
(4954048, 717912, 3936, '<td valign="top">Very nice depth of field.  I like the tone of the monchrome image.</td>', 'Very nice depth of field.  I like the tone of the monchrome image.', '2008-09-13 21:38:11.000000', NULL, 1),
(4954050, 720064, 3936, '<td valign="top">I''m not seeing where the subject is trying to move the object.  Looks like he is going to climb it.  I like the contrast and the color.</td>', 'I''m not seeing where the subject is trying to move the object.  Looks like he is going to climb it.  I like the contrast and the color.', '2008-09-13 21:39:47.000000', NULL, 1),
(4954051, 719139, 3936, '<td valign="top">Focus appears off, I can''t seem to find anything in sharp focus.</td>', 'Focus appears off, I can''t seem to find anything in sharp focus.', '2008-09-13 21:41:03.000000', NULL, 1),
(4954053, 718927, 3936, '<td valign="top">I don''t see the immovable theme in this image.  Photo is very grainy and there doesn''t seem to be a real reason to do this.  Looks way over processed.</td>', 'I don''t see the immovable theme in this image.  Photo is very grainy and there doesn''t seem to be a real reason to do this.  Looks way over processed.', '2008-09-13 21:42:26.000000', NULL, 1),
(4954055, 719062, 3936, '<td valign="top">Image appears soft, like focus is off.  The washed out bright foreground is distracting.  I''m not seeing the theme here.</td>', 'Image appears soft, like focus is off.  The washed out bright foreground is distracting.  I''m not seeing the theme here.', '2008-09-13 21:43:46.000000', NULL, 1),
(4954185, 720064, 33769, '<td valign="top">Beautiful and very DPC friendly :-) HIGH SCORE :-) Lovely colors-- nice silhouette! ;)</td>', 'Beautiful and very DPC friendly :-) HIGH SCORE :-) Lovely colors-- nice silhouette! ;)', '2008-09-13 23:57:57.000000', NULL, 1),
(4954189, 718436, 61818, '<td valign="top">Is that supposed to be a cigarette in Lenin''s hand?  Lenin was a non-smoker.  Very odd.</td>', 'Is that supposed to be a cigarette in Lenin''s hand?  Lenin was a non-smoker.  Very odd.', '2008-09-14 00:02:04.000000', NULL, 1),
(4954193, 720255, 61818, '<td valign="top">It''s not a snapshot.  I think in this challenge that immediately gets you the blue ribbon.</td>', 'It''s not a snapshot.  I think in this challenge that immediately gets you the blue ribbon.', '2008-09-14 00:03:10.000000', NULL, 1),
(4954196, 718456, 61818, '<td valign="top">Pretty colors.  Imagine this will be on the front page.  Not sure what''s immovable about something that happens to be lying still.  The two are not the same.</td>', 'Pretty colors.  Imagine this will be on the front page.  Not sure what''s immovable about something that happens to be lying still.  The two are not the same.', '2008-09-14 00:04:33.000000', NULL, 1),
(4954202, 719644, 61818, '<td valign="top">Can''t quite connect ''acceleration'' with ''immovable''.  Good luck.</td>', 'Can''t quite connect ''acceleration'' with ''immovable''.  Good luck.', '2008-09-14 00:07:10.000000', NULL, 1),
(4954205, 720129, 61818, '<td valign="top">Especially when the ground is tilted to the left.</td>', 'Especially when the ground is tilted to the left.', '2008-09-14 00:09:19.000000', NULL, 1),
(4954225, 720293, 3936, '<td valign="top">I like the picture.  The butterfly is nice and sharp, with excellent colors. The soft focus on the boy, helps the butterfly pop.</td>', 'I like the picture.  The butterfly is nice and sharp, with excellent colors. The soft focus on the boy, helps the butterfly pop.', '2008-09-14 00:30:11.000000', NULL, 1),
