(4954461, 720053, 87898, '<td valign="top">I like the tones in this photo, but I think theres a bit too much grain. It looks like its been sharpened a bit too much.</td>', 'I like the tones in this photo, but I think theres a bit too much grain. It looks like its been sharpened a bit too much.', '2008-09-14 08:19:50.000000', NULL, 1),
(4954594, 719922, 98532, '<td valign="top">perfect !!!</td>', 'perfect !!!', '2008-09-14 12:03:35.000000', NULL, 1),
(4954612, 720260, 87898, '<td valign="top">I love this! The only thing that bothers me is the green border, but I think that might just be me. :).</td>', 'I love this! The only thing that bothers me is the green border, but I think that might just be me. :).', '2008-09-14 12:23:50.000000', NULL, 1),
