(4955114, 720260, 97225, '<td valign="top">I''m sure not buying any tickets on that train. Good take on subject and nice sharp focus.</td>', 'I''m sure not buying any tickets on that train. Good take on subject and nice sharp focus.', '2008-09-14 20:51:54.000000', NULL, 1),
(4955118, 719047, 97225, '<td valign="top">Good photo. The bend in the trunk makes it look as if it is yeilding a little to pressure.</td>', 'Good photo. The bend in the trunk makes it look as if it is yeilding a little to pressure.', '2008-09-14 20:53:32.000000', NULL, 1),
