(4955139, 718291, 97225, '<td valign="top">Lovely photo. How long before the bulldozers move in and put in a shopping complex?(9)</td>', 'Lovely photo. How long before the bulldozers move in and put in a shopping complex?(9)', '2008-09-14 21:06:06.000000', NULL, 1),
(4955140, 719845, 97225, '<td valign="top">I love this. It looks great and the concept is brilliant.</td>', 'I love this. It looks great and the concept is brilliant.', '2008-09-14 21:06:53.000000', NULL, 1),
(4955141, 719644, 97225, '<td valign="top">This is a bit crowded for my taste, but I guess it would be pretty hard to get a clear shot.</td>', 'This is a bit crowded for my taste, but I guess it would be pretty hard to get a clear shot.', '2008-09-14 21:08:16.000000', NULL, 1),
