(4955191, 718456, 33672, '<td valign="top">Great tones.</td>', 'Great tones.', '2008-09-14 22:13:54.000000', NULL, 1),
(4955248, 719145, 32011, '<td valign="top">Nice use of the lens.  Colours are strong... perhaps a little too much on the saturation (notice the blue halo at the back of the green t-shirt).  I''m picking this for a red or yellow ribbon.  Well done!</td>', 'Nice use of the lens.  Colours are strong... perhaps a little too much on the saturation (notice the blue halo at the back of the green t-shirt).  I''m picking this for a red or yellow ribbon.  Well done!', '2008-09-14 22:57:56.000000', NULL, 1),
(4955252, 719845, 32011, '<td valign="top">Absolutely beautiful.  Colours are superb.  Concept is excellent... nice to see something that meets the challenge without resorting to pulling or pushing a heavy object.</td>', 'Absolutely beautiful.  Colours are superb.  Concept is excellent... nice to see something that meets the challenge without resorting to pulling or pushing a heavy object.', '2008-09-14 22:59:37.000000', NULL, 1),
(4955256, 718491, 32011, '<td valign="top">Beautiful idea, well executed.  Sharp and clean image, effectively conveying strong emotion.  Hope it does well... I like the images that look at the deeper meaning of the challenge theme while still meeting the challenge criteria.</td>', 'Beautiful idea, well executed.  Sharp and clean image, effectively conveying strong emotion.  Hope it does well... I like the images that look at the deeper meaning of the challenge theme while still meeting the challenge criteria.', '2008-09-14 23:04:05.000000', NULL, 1),
(4955320, 719845, 23098, '<td valign="top">Good one for the challenge.</td>', 'Good one for the challenge.', '2008-09-14 23:56:09.000000', NULL, 1),
(4955322, 720255, 23098, '<td valign="top">Tension and struggle are nicely portrayed.  Good one.</td>', 'Tension and struggle are nicely portrayed.  Good one.', '2008-09-14 23:56:57.000000', NULL, 1),
(4955323, 720161, 23098, '<td valign="top">Sharp, clean and an obvious struggle. Great light.</td>', 'Sharp, clean and an obvious struggle. Great light.', '2008-09-14 23:57:23.000000', NULL, 1),
